# Jest 範例

假設有一個計算折扣價的函式：

```js
// discount.js
function calculateDiscount(price, rate) {
  if (typeof price !== 'number' || typeof rate !== 'number') {
    throw new TypeError('price 與 rate 必須是數字');
  }
  if (price < 0) {
    throw new RangeError('price 不可為負數');
  }
  if (rate < 0 || rate > 1) {
    throw new RangeError('rate 必須介於 0 到 1');
  }
  return price * (1 - rate);
}

module.exports = { calculateDiscount };
```

對應的測試：

```js
// discount.test.js
const { calculateDiscount } = require('./discount');

describe('calculateDiscount', () => {
  // 正常情況
  test('價格 100、折扣 20% 時，應回傳 80', () => {
    // Arrange
    const price = 100;
    const rate = 0.2;

    // Act
    const result = calculateDiscount(price, rate);

    // Assert
    expect(result).toBe(80);
  });

  // 邊界情況
  test('折扣為 0 時，應回傳原價', () => {
    expect(calculateDiscount(100, 0)).toBe(100);
  });

  test('折扣為 100% 時，應回傳 0', () => {
    expect(calculateDiscount(100, 1)).toBe(0);
  });

  test('價格為 0 時，應回傳 0', () => {
    expect(calculateDiscount(0, 0.5)).toBe(0);
  });

  // 浮點數要用 toBeCloseTo
  test('小數運算應在可接受的誤差範圍內', () => {
    expect(calculateDiscount(19.99, 0.1)).toBeCloseTo(17.991, 3);
  });

  // 例外情況
  test('價格為負數時，應丟出 RangeError', () => {
    expect(() => calculateDiscount(-1, 0.1)).toThrow(RangeError);
  });

  test('折扣率超出 0~1 時，應丟出 RangeError', () => {
    expect(() => calculateDiscount(100, 1.5)).toThrow(RangeError);
    expect(() => calculateDiscount(100, -0.1)).toThrow(RangeError);
  });

  test('參數不是數字時，應丟出 TypeError', () => {
    expect(() => calculateDiscount('100', 0.1)).toThrow(TypeError);
  });
});
```

執行方式：

```bash
npm install --save-dev jest
npx jest
```

